      "title": "Trapped in the Burning Cottage",
      "start_block": "B012",
      "end_block": "B047",
      "hook": "A violent crash as the bedroom door is kicked open, revealing Alexander framed in the blazing doorway as he shouts 'Juliana! Get up!'",
      "cliffhanger": "Juliana looks up in sheer terror as the ceiling rafter splits violently apart above her, screaming 'Alexander!'",
      "why": "Starts with a rescue burst and ends on a life-or-death cliffhanger before the beam falls.",
      "context_gap": "Why the cottage is on fire and who set it."
    },
    {
      "title": "The Ledger or Her Life",
      "start_block": "B030",
      "end_block": "B052",
      "hook": "Close-up of the antique leather-bound herbal ledger on a burning table, its pages beginning to curl and singe as Juliana screams 'The ledger!'",
      "cliffhanger": "Alexander lies on top of Juliana, cradling her cheek tenderly and panting 'I've got you' as the beam crashes behind them.",
      "why": "A desperate choice between a mother's memory and survival, ending on a tender but unresolved moment amid the flames.",
      "context_gap": "The ledger's sentimental value to Juliana."
    },
    {
      "title": "Vengeance in His Eyes",
      "start_block": "B074",
      "end_block": "B081",
      "hook": "Alexander's cold, ominous voice: 'Someone wanted us out' as he holds a weeping Juliana in his arms.",
      "cliffhanger": "Alexander's grim, unyielding profile stares into the inferno with unshakeable resolve as the swelling score echoes.",
      "why": "A quiet, menacing threat that promises revenge, ending on his hardened face before he answers what he will do.",
      "context_gap": "Who 'they' are and why they targeted the couple."
    }
  ],
  "moments": [
    {
      "start_block": "B012",
      "end_block": "B014",
      "kind": "hook",
      "description": "Alexander kicks open the burning bedroom door and shouts for Juliana to get up."
    },
    {
      "start_block": "B030",
      "end_block": "B035",
      "kind": "emotional",
      "description": "Juliana spots her mother's burning ledger and screams 'No! No!' as Alexander tries to pull her back."
    },
    {
      "start_block": "B044",
      "end_block": "B049",
      "kind": "cliffhanger",
      "description": "The ceiling rafter splits above Juliana as Alexander tackles her to the floor, the beam crashing where she stood."
    },
    {
      "start_block": "B076",
      "end_block": "B078",
      "kind": "reveal",
      "description": "Alexander's face hardens into lethal fury as he vows 'They took our home. I will not let them take anything else now.'"
    }
  ]
}
